<?php
$page_title='ศูนย์ช่วยเหลือลูกค้า';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);try{$id=(int)($_POST['ticket_id']??0);$body=trim($_POST['message']??'');$status=$_POST['status']??'waiting_customer';if(!in_array($status,['open','waiting_customer','waiting_staff','resolved','closed'],true))throw new RuntimeException('สถานะไม่ถูกต้อง');$s=$db->prepare('SELECT * FROM support_tickets WHERE id=?');$s->execute([$id]);$ticket=$s->fetch();if(!$ticket)throw new RuntimeException('ไม่พบเคส');$db->beginTransaction();if($body!=='')$db->prepare('INSERT INTO support_messages(ticket_id,sender_user_id,message,is_staff) VALUES(?,?,?,1)')->execute([$id,(int)$_SESSION['user_id'],mb_substr($body,0,5000)]);$db->prepare('UPDATE support_tickets SET status=?,last_message_at=NOW() WHERE id=?')->execute([$status,$id]);createNotification($db,(int)$ticket['user_id'],'support','อัปเดตเคส '.$ticket['ticket_no'],$body?:'สถานะเคสได้รับการอัปเดต',BASE_URL.'support.php?id='.$id);auditLog($db,'support.ticket.update','support_ticket',$id,['status'=>$ticket['status']],['status'=>$status]);$db->commit();$message='อัปเดตเคสแล้ว';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'ดำเนินการไม่สำเร็จ';}}
$id=(int)($_GET['id']??0);$selected=null;$messages=[];if($id){$s=$db->prepare('SELECT t.*,u.username,u.email,o.order_no FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN orders o ON o.id=t.order_id WHERE t.id=?');$s->execute([$id]);$selected=$s->fetch();if($selected){$s=$db->prepare('SELECT m.*,u.username FROM support_messages m LEFT JOIN users u ON u.id=m.sender_user_id WHERE ticket_id=? ORDER BY m.id');$s->execute([$id]);$messages=$s->fetchAll();}}$tickets=$db->query("SELECT t.*,u.username FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY FIELD(t.status,'waiting_staff','open','waiting_customer','resolved','closed'),FIELD(t.priority,'urgent','high','normal','low'),t.last_message_at DESC")->fetchAll();require __DIR__.'/../includes/admin_header.php';
?><header class="admin-page-header"><div><p class="eyebrow">CUSTOMER CARE</p><h1>ศูนย์ช่วยเหลือลูกค้า</h1><p>รับเรื่อง ตอบกลับ และติดตามจนปิดเคส</p></div></header><?php if($message):?><div class="alert alert-success"><?php echo e($message);?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?php echo e($error);?></div><?php endif;?><section class="admin-panel"><table><thead><tr><th>เคส</th><th>ลูกค้า</th><th>หัวข้อ</th><th>สถานะ</th><th></th></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td><?php echo e($t['ticket_no']);?></td><td><?php echo e($t['username']);?></td><td><?php echo e($t['subject']);?></td><td><?php echo e($t['status']);?></td><td><a class="btn btn-outline" href="?id=<?php echo (int)$t['id'];?>">เปิดเคส</a></td></tr><?php endforeach;?></tbody></table></section><?php if($selected):?><section class="admin-panel" style="margin-top:20px;padding:24px"><h2><?php echo e($selected['subject']);?> · <?php echo e($selected['ticket_no']);?></h2><p><?php echo e($selected['username']);?> · <?php echo e($selected['email']);?><?php if($selected['order_no']):?> · ออเดอร์ <?php echo e($selected['order_no']);?><?php endif;?></p><?php foreach($messages as $m):?><article style="padding:14px;margin:10px 0;background:<?php echo $m['is_staff']?'#eef5f1':'#fff7ed';?>"><strong><?php echo $m['is_staff']?'ทีมงาน':e($m['username']);?></strong><p><?php echo nl2br(e($m['message']));?></p></article><?php endforeach;?><form method="post" style="display:grid;gap:12px"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="ticket_id" value="<?php echo (int)$selected['id'];?>"><textarea name="message" rows="4" maxlength="5000" placeholder="ข้อความตอบกลับ"></textarea><select name="status"><option value="waiting_customer">รอลูกค้าตอบ</option><option value="resolved">แก้ไขแล้ว</option><option value="closed">ปิดเคส</option><option value="waiting_staff">รอทีมงาน</option></select><button class="btn btn-primary">บันทึกและแจ้งลูกค้า</button></form></section><?php endif;?><?php require __DIR__.'/../includes/admin_footer.php';?>
